import { HINTS } from '../listening-hints';

export const DATA_07: ListeningTest[] = [
  { id: "listening-19", title: "Đề 19", subtitle: "35 câu · 40 phút", durationMin: 40, parts: [
    { n: 1, title: "Part 1", hint: HINTS[1], recordings: [
      { id: "listening-19-p1", label: "Bài nghe Part 1", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-19/part1-1.mp3", script: "Question 1.\nOK everybody. This next exercise is a bit difficult but it’s really good for your legs. All you do is put your back against the wall place your feet about half a metre away from the wall move your back down the wall so your knees are bent at 90 degrees. Now, put your hands out straight in front of you right make sure your head is against the wall. Now, see how long you can stay like that. If you do two minutes, you’re doing well.\nQuestion 2.\nBecause of the ski jumping finals we’re late finishing so there are some changes to this evening’s programmes. We won’t now show the Nature Programme about the dolphins found near the Florida coast at nine o’clock. Instead, Tim Wong’s Chinese Kitchen will be at this time an hour later than advertised. You can see the Nature Programme at its usual time next week.\nQuestion 3.\nAll fans of Peter Robbins should go to the South Street book store tomorrow afternoon where Peter will sign copies of his book Love of Life and answer questions. He is expected at a quarter past two and promises to stay until half past three when he has to leave for another appointment. Get there as soon as you can because if it’s anything like Peter’s last visit queues will start to form at quarter to two or even earlier. Don’t miss this opportunity to meet everyone’s favourite writer.\nQuestion 4.\nHere is the weather forecast. Today will be very cloudy although it won’t rain until the evening. The weather tomorrow will be the same as yesterday sunshine and showers. But the weekend looks good plenty of sunshine and very little rain.\nQuestion 5.\nNow you won’t need any money for the bus or your entrance ticket to the zoo tomorrow because that’s already paid for. But bring some small change for when you get thirsty and want a drink. The only food or drink allowed on the bus is fruit. Bring some with you because it’s a long trip and you’ll get hungry. No food or drink must be taken into the zoo. And you’ll need to bring all your coloured pencils for the work I’m going to ask you to do there.\nQuestion 6.\nAnd now for tomorrow’s weather. The day will start showery and windy. Those winds should disappear by late morning but the wet weather will continue until well into the evening. Although we might see some bright sunny periods between the showers early on by midday, it will be cloudy with temperatures of no more than ten or twelve degrees centigrade.\nQuestion 7.\nIt was really strange going back to Redmond where I used to live. Everything has changed so much. I went to see my old house. It used to have trees in the garden and a hedge in the front. Well, the people who own it now have built another bedroom over the top of the garage and removed the trees and hedge so they have more room to park their cars. It made me feel really sad because it looked so different.\nQuestion 8.\nComing up next on The Science Channel is the latest documentary produced and presented by photographer Daniel Hamilton, who made the prize winning series about African animals which you may have seen last year. His latest series is simply called Earth and viewers can enjoy some amazing photography with pictures of the planet shot from cameras in space using the latest satellite technology. So sit back, relax and enjoy!", questions: [{ q: "Which part(s) of the body does the exercise affect well?", options: ["knees", "back", "hands", "legs"], answer: 3 }, { q: "Which TV programme is on at 9 o’clock tonight?", options: ["Ski jumping finals", "Nature Programme", "Tim Wong’s Chinese Kitchen", "a programme about dolphins"], answer: 2 }, { q: "What time will the writer arrive at the bookshop?", options: ["At 1.45", "At 2.15", "At 3.30", "At 2.30"], answer: 1 }, { q: "What will the weather be like tomorrow?", options: ["rainy", "cloudy", "sunny", "both sunny and rainy"], answer: 3 }, { q: "What should the students take on the school trip?", options: ["Drink, fruit and some change", "Drink, fruit and coloured pencils", "Fruit, some change and coloured pencils", "fruit and coloured pencils"], answer: 2 }, { q: "What will the weather be like tomorrow afternoon?", options: ["rainy", "windy", "sunny", "cloudy"], answer: 0 }, { q: "What does the woman’s house look like now?", options: ["It has another bedroom over the garage", "It has trees in the garden", "It has a hedge in the front", "It has trees in the garden and a hedge in the front."], answer: 0 }, { q: "What is the next TV program about?", options: ["the satellite", "the Earth", "African animals", "photography"], answer: 1 }] } ], },
    { n: 2, title: "Part 2", hint: HINTS[2], recordings: [
      { id: "listening-19-p2", label: "Bài nghe Part 2", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-19/part1-2.mp3", script: "Conversation 1 (Q.9-12)\nM: And today in the studio we have a familiar face on television, Angela Bond the news reporter. Angela, your job has taken you all over the world, hasn’t it?\nW: Yes. I’ve reported from a number of countries in Asia and I’ve just returned from the United States. I must say, it’s good to be able to unpack my suitcase now that the job has brought me to Britain for at least six months.\nM: Is the travelling what you enjoy about the job?\nW: It’s certainly interesting, but it can be annoying never knowing where I’m going to be next week! For me, the really exciting thing is being somewhere when a big news story is taking place and seeing it develop. Sometimes that can be quite dangerous, but all jobs have their disadvantages! And travelling gives me the chance to collect souvenirs.\nM: What kind of things?\nW: Mostly things for my flat. I’m mad about anything Chinese and so when I was in Hong Kong, I got a really nice table and some chairs and in Turkey I spend a lot of money on carpets. Then I’ve got pictures and other bits of art from Thailand and India. The flat’s getting a bit crowded!\nM: It sounds colourful! Do you have a regular working day?\nW: Not really. At the moment, I’m one of the team that reads the evening news so sometimes I’m on at six thirty, and sometimes at ten o’clock. But that’s at the end of the day. It all starts in the morning at eight thirty when I phone the office to see what has happened and what they want me to go and report on.\nM: So you don’t have much time for a social life?\nW: It’s better now I’m in London and can see my boyfriend more often. My sister introduced us. He came round for dinner when I was staying with her a year ago. We have a lot in common. He’s a lawyer and I studied law at university. Also we’ve found that we lived in Hong Kong at the same time, although we never met.\nM: What do you like to do in your free time?\nW: Well, cooking is something new I’m trying because I can’t do it when I’m travelling. But I’m not very good at it yet so I find it a bit stressful. One of the best things I’ve bought recently was a boat and when I want to feel calm and peaceful I go for a sail on the river. It never fails!\nM: Angela, thanks.\nConversation 2 (Q.13-16)\nW: Oh, what a wonderful view! I’m here with Jack Williams, who’s telling me about his home town of Swanton.\nM: Yes, the top of this hill is the best place to see the area. Swanton is on the coast you can see the harbour from here but in fact the town is built along the river Dean. This river comes from a lake in the mountains, over there in the distance then flows down to the flat land below us where the town is built.\nW: What do you most like about living here?\nM: About Swanton? Oh, it’s an important industrial town and a port so there’s lots of activity. And there’s a forest behind the town with interesting wildlife. But the most exciting thing for me is the mountains. I go climbing whenever I get the chance.\nW: What about entertainment?\nM: There’s plenty of entertainment. A big centre was built last year to encourage the arts - very modern. It’s got a cinema, a theatre and an art gallery. And there’s football. The local team hasn’t done so well lately. A few years ago we nearly won the Cup. And our area is famous for music not in Swanton itself but there’s a well-known music festival in the next town.\nW: But there are problems with the environment.\nM: We’re working on that. The river was a great place for fish but the water got so polluted by the factories that most of the fish disappeared. Well, we’ve cleaned the river up now, and the fish are starting to come back. But I’m unhappy about Swanton woods. The trees are quite healthy but if you look, there are no birds there, and that’s because pollution has reduced the number of insects.\nW: Swanton’s growing fast. Are you pleased about the way it’s changed?\nM: You’ve got to move with the times. It was completely different when I was a boy. In those days everybody worked in the factories, and the families all knew each other. Maybe it was a little boring. Today there are hundreds of different companies and so many new houses that some people don’t even know their neighbours. There are disadvantages, but it’s impossible to be bored with all the things going on.\nW: And what about Swanton’s future?\nM: Education is important to us. We have a fine university which specialises in advanced technology. And a huge shopping centre, just built, which is bringing in double the number of visitors - good news for us. And last year we improved our airport, so more planes can come in.\nConversation 3 (Q.17-20)\nM: My guest today is the star of the London Ballet Company, 22 years old Elena Karpov. Elena you were born in Bulgaria. Did you always want to be a dancer?\nW: Well, I was a very lively little girl, so at the age of seven my mother sent me to gymnastics classes. When I was nine, I went on to ballet lessons and from that moment I knew that I wanted to spend my life dancing. Two years later, when I was eleven, I won a place at the New York Ballet School.\nM: So you had to move to the United States. Did you miss your family?\nW: Oh yes. At first it was difficult being away from home and not knowing a lot of English. But it taught me how to look after myself and not to depend on others. There were other Bulgarian students there and we actually found it quite easy to learn enough English to take part in the lessons with the other students.\nM: Tell us about your latest role with the London Ballet Company.\nW: I’m going to dance the part of Cinderella. It’s a story about a poor girl who marries a handsome prince. My parents used to read it to me when I was little. I’d never seen the ballet before, but I already knew the music really well. I’m sure children will love the ballet.\nM: What do you do when you’re not practising or performing?\nW: Before I joined this company I spent two weeks going round London as a tourist. I don’t have time for sightseeing now, but I love trying on the latest fashions with my friends. I’m always buying new jeans and trainers! I’m not too keen on discos and nightclubs I dance enough during the day!\nM: You must have lots of fans?\nW: Quite a few! They always ask for a photograph of me, but unfortunately I don’t have many to give away. I sometimes sign their programmes instead and if I can I give them one of the flowers I’ve received from the audience. They always ask for tickets, but of course that’s not possible.\nM: What’s been the best thing that’s happened in your career so far?\nW: Well, I’ve been a guest dancer with ballet companies in Moscow and Vienna and I appeared twice on television in Bulgaria and met the president! I shall never forget that! But the most satisfying thing for me is that I’m paid for doing what I really enjoy - dancing!\nM: Elena, thank you for talking to us.\nW: Thank you.", questions: [{ q: "Why is Angela currently in Britain?", options: ["Her work requires her to stay there for at least six months", "Her work has brought her there after an assignment in the United States", "Her work has brought her there after several assignments in Asia", "Her work allows her to spend more time with her boyfriend there"], answer: 0 }, { q: "What does Angela find most exciting about her work?", options: ["Being able to travel when major stories take place", "Being able to watch a major story develop as it happens", "Being able to meet people while reporting in different countries", "Being able to collect interesting things from the places she visits"], answer: 1 }, { q: "What did Angela buy in Hong Kong?", options: ["Furniture for her flat", "Carpets for her flat", "Pictures and other artwork", "Chinese objects for her flat"], answer: 0 }, { q: "How did Angela first meet her boyfriend?", options: ["They met while they were both living in Hong Kong", "They met while she was studying law at university", "They met after her sister introduced them to each other", "They met after working together on a television assignment"], answer: 2 }, { q: "How is Swanton situated geographically?", options: ["It is built beside a lake that lies among the mountains", "It is built along a river that flows towards the coast", "It is built on a hill overlooking the river and the coast", "It is built between the mountains and the coast, away from the river"], answer: 1 }, { q: "What has recently been added to Swanton's entertainment facilities?", options: ["A modern centre containing a cinema, theatre and art gallery", "A modern centre containing a football ground, theatre and art gallery", "A new festival containing music, theatre and art activities", "A new centre containing a cinema, football ground and music venue"], answer: 0 }, { q: "Why have there been fewer birds in Swanton woods?", options: ["Pollution has damaged the trees where birds normally live", "Factory pollution has reduced the fish available to birds", "Pollution has reduced the insects that birds feed on", "New housing has reduced the amount of forest available to birds"], answer: 2 }, { q: "What does Jack say about the changes in Swanton?", options: ["The town is more active now, although some changes have disadvantages", "The town is more crowded now, although people still know their neighbours", "The town is more industrial now, although fewer people work in factories", "The town is more developed now, although there are fewer things happening"], answer: 0 }, { q: "When did Elena become certain that she wanted to be a dancer?", options: ["When she started gymnastics at the age of seven", "When she began ballet lessons at the age of nine", "When she entered the New York Ballet School at the age of eleven", "When she moved to the United States to continue her training"], answer: 1 }, { q: "What does Elena say about her role as Cinderella?", options: ["She knew the story well but had never seen the ballet before", "She knew the music well but had never seen the ballet before", "She had seen the ballet before but did not know the music well", "She had known both the ballet and its music since she was a child"], answer: 1 }, { q: "What does Elena enjoy doing with her friends?", options: ["Trying on new clothes and buying fashionable items", "Exploring London and visiting its tourist attractions", "Going to discos and dancing after performances", "Watching ballet performances and discussing the latest fashions"], answer: 0 }, { q: "What does Elena find most satisfying about her career?", options: ["Being invited to perform with companies in other countries", "Having the chance to appear on television in Bulgaria", "Being able to meet important people through her work", "Being paid to do something she genuinely enjoys"], answer: 3 }] } ], },
    { n: 3, title: "Part 3", hint: HINTS[3], recordings: [
      { id: "listening-19-p3", label: "Bài nghe Part 3", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-19/part1-3.mp3", script: "Talks/Lectures 1 (Q.21-25)\nHello, I’m Sarah Brown, and I’m here to tell you about my job as a weather forecaster. I’ve been a weather forecaster for a television company for seven years and two years ago I became the head of the weather department. Now, I divide my time equally between presenting weather forecasting on television and managing the weather department which has a staff of eleven. At thirty years old I’m the youngest ever head of weather and the first woman to do the job. Since our news and weather service goes out all round the world, we all take turns to work at night I prefer that to doing the show when I have to get up at four in the morning.\nI normally work an eight hours day and at that time I do ten or twelve forecasts. Before doing a weather forecast, I study data on the computer. This is the information I use in my forecasts. There isn’t much time to learn what I have to say but fortunately I’ve never forgotten my words so I don’t get nervous. My husband and I try to have the same free days, but neither of us has a regular pattern of work. He’s a pilot on long distance flights, so although he works hard he has a lot more time at home than I do. We moved to our present house about a year ago, and he’s enjoying painting it. I took up flying as a hobby five years ago. I hope to get my pilot’s licence this year but because of the job, I haven’t been to the flying school for ages For exercise I swim and ski and I like running.\nI’m really proud of myself for running in the London Marathon it’s a forty kilometre race and I never thought I could manage it! My husband plays tennis, and we sometimes play together, but he’s better than me so I never win. Because I’m on world news, people sometimes recognise me in really distant places. Once, in an Indian village, an old man took me to have my photo taken with all his family. I get some lovely letters one person wrote to say that my smile made her feel happy all day. People occasionally even write and ask me to marry them!\nTalks/Lectures 2 (Q.26-30)\nThank you all for coming to my talk this evening. It’s nice to see so many people in the audience. For those of you who don’t know very much about PS Camping let me start by giving you some background information about the company. The company started twenty five years ago. It actually opened as a retail chain selling camping equipment, and then twenty years ago it bought a small number of campsites in the UK and began offering camping holidays.\nThe company grew rapidly and has been providing holidays in continental Europe for the last fifteen years. If you book a camping holiday with us you’ll have a choice of over 300 sites. In Italy we now have some 64 sites that we either own, or have exclusive use of. France is where we have the majority of sites, and we currently have a project to expand into Switzerland. We also have a number of sites in Northern Spain particularly in the mountainous region of Picos de Europa. We’ve upgraded all these Spanish sites, and improved them considerably from their original three stars rating. We believe our holidays offer superb facilities for the whole family.\nParents who want their children to be fully occupied for all or part of the day can take advantage of our children’s activities. These are organised by our well-qualified and enthusiastic staff. Each day kicks off with a sports match perhaps football, or volleyball, followed by an hour of drama for everyone. This may include singing or dancing, mime or other activities. In the afternoon, there’s a different art activity for each day of the week including a poster competition or model making. What’s more, our sites are truly child friendly and, with this in mind we operate a no noise rule in the evenings Children’s evening activities usually finish at 9.30 or occasionally 10, and from 10.30 holiday makers are expected to be quiet in the areas where there are tents. We want nothing to go wrong on a PS Camping holiday, but if it does, we also want all customers to be insured.\nIf you haven’t organised an annual insurance policy of your own you’ll need to take out the low cost cover we offer and we require that you arrange this when you make your holiday reservation. There are many advantages to choosing PS Camping, and to recommending it to others. As a regular customer you’ll be kept informed of special offers and your friends can benefit from ten percent off their holiday or book a luxury tent for the price of a standard one. In return, we’ll send you a thank you present, which you can choose from a list of high quality items.\nTalks/Lectures 3 (Q.31-35)\nGood morning. I’m very pleased to have been invited along to your club to talk about our Charity Sponsored Walking Holiday for Education Aid. I’ll start by giving you a brief overview of what it entails. First of all let me explain what we mean by ‘sponsored’ here. This is where people promise to donate money to the charity if you achieve your goal in this case to walk a certain number of miles. Basically we are organizing a ten days holiday, from the sixth to the sixteenth of November with eight days actual walking, trekking in the Semira Mountains. Let’s have a look at some of the details. We require you to raise sponsorship money of at least $3,200 paying $250 of it up front as a deposit and the rest in stages throughout the year. Out of this, about 35% will go on your expenses and that leaves 65% guaranteed to go to the charity. Which brings me to the most important part.\nThis trek is being specifically organized to help education in the Semira region. Last year we helped train teachers for the disabled, and this year we’re focusing on the pupils. Each of the walkers’ sponsorship money will go to help an individual special needs pupil in one of the mountain schools. In the second part of the talk I’ll be giving you a lot more details, but back to the basic information. Age limits is the second time we have run this kind of holiday and um, on the first we even had an eight-year old. But we found it was wise to establish limits this time. You have to be at least eighteen and the top limit is now seventy though you need to obtain a health certificate from your doctor if you are over sixty years old.\nNow, the Semira Mountains are among the highest in the world but you mustn’t be too daunted we will mainly be trekking in the foothills only, although there will be spectacular views even in the foothills. However, you will need to be extremely fit if you aren’t now and you’re interested in coming with us. You have plenty of time to get into shape. You will be sleeping in tents so you must have quite a bit of equipment with you but you will be helped by local assistants. Your bedding and so forth will be carried by them.\nWe ask that you only walk with a small rucksack with needs for the day. I don’t think I’ve really said enough about the marvellous area you’ll be walking in. Let’s have a look at some of the sights you’ll be seeing. Apart from these spectacular snow covered peaks and valleys, there are marvellous historic villages, the area has been famous for centuries for making beautiful carpets although recently there has been a trend to move into weaving blankets and wood carving. The people are extremely friendly and welcoming. We deliberately keep the parties small in size to minimize disruption to people and landscape.\nNguồn: https://vstepowl.com/listening/de-thi/?exam=listening-19", questions: [{ q: "How long had Sarah worked as a weather forecaster before becoming head of the department?", options: ["Eleven years", "Two years", "Five years", "Seven years"], answer: 2 }, { q: "Why does Sarah prefer working at night?", options: ["She can work more easily around her husband's schedule", "She can avoid the busiest period of the news service", "She can avoid presenting the weather early in the morning", "She can have more free time during the daytime"], answer: 2 }, { q: "Why does Sarah say she does not get nervous when presenting forecasts?", options: ["She has never forgotten what she has to say", "She relies on detailed notes while speaking on television", "She always has plenty of time to prepare her forecasts", "She has become comfortable with making mistakes on air"], answer: 0 }, { q: "What does Sarah say about her and her husband's working schedules?", options: ["His long-distance flights mean that he spends little time working at home", "They both work regular hours and usually have the same days off", "Their different schedules make it difficult to arrange the same free days", "His demanding job leaves him with less time at home than Sarah"], answer: 2 }, { q: "What does Sarah suggest about running the London Marathon?", options: ["She decided to enter the race because she wanted to improve her fitness", "She was surprised that she was able to complete such a demanding race", "She found the marathon easier than she had originally expected", "She had spent several years preparing specifically for the marathon"], answer: 1 }, { q: "How long after the company was founded did it begin offering camping holidays?", options: ["Twenty-five years later", "Five years later", "Twenty years later", "Fifteen years later"], answer: 1 }, { q: "Where does the company currently have the largest number of campsites?", options: ["Northern Spain", "Switzerland", "Italy", "France"], answer: 3 }, { q: "How are the children's afternoon activities organised?", options: ["Children choose between several activities each morning", "The same sports activity is repeated throughout the week", "A different art activity is offered on each day", "A different drama activity is offered every afternoon"], answer: 2 }, { q: "What does the insurance arrangement imply for customers who already have their own annual policy?", options: ["They must provide proof of their existing policy when booking", "They can choose between two different PS Camping policies", "They do not need to take out the company's insurance cover", "They still have to buy additional cover from PS Camping"], answer: 2 }, { q: "What does a regular customer receive for recommending PS Camping to a friend?", options: ["A special offer on their next booking", "A thank-you gift of their own choice", "A luxury tent for their next holiday", "A discount on their friend's holiday"], answer: 1 }, { q: "How many days of the holiday will involve actual walking?", options: ["Four days", "Ten days", "Six days", "Eight days"], answer: 3 }, { q: "What percentage of the sponsorship money is guaranteed to go to the charity?", options: ["65%", "25%", "35%", "50%"], answer: 0 }, { q: "What additional requirement applies to participants over sixty?", options: ["They must receive approval from the local organisers", "They must provide a health certificate from their doctor", "They must remain in the foothills throughout the holiday", "They must have previous experience of mountain trekking"], answer: 1 }, { q: "Why will walkers only need to carry a small rucksack?", options: ["Walkers will only need equipment for the first part of each day", "Local assistants will carry their bedding and other equipment", "The organisers will transport their belongings between villages", "Most of their equipment will already be provided in the tents"], answer: 1 }, { q: "What change in local crafts does the speaker mention?", options: ["Wood carving has become more important than carpet-making", "Traditional carpet-making has recently become less popular", "The region is becoming increasingly known for blanket weaving", "Carpet-making has recently been replaced by wood carving"], answer: 2 }] } ], },
  ] },
  { id: "listening-20", title: "Đề 20", subtitle: "35 câu · 40 phút", durationMin: 40, parts: [
    { n: 1, title: "Part 1", hint: HINTS[1], recordings: [
      { id: "listening-20-p1", label: "Bài nghe Part 1", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-20/part1-1.mp3", script: "Question 1.\nHi everyone, and welcome to City Wildlife Park. I’ll explain where things are and then you’re free to go wherever you want. In front of us are some empty cages where the rabbits live. They’re free to run about in the long grass, but come back to their cages when they’re hungry! If you’re interested in ducks, surprisingly they’re not right here in the pond, but over there in one of their favourite places, near the dustbins. And we keep goats in the field here, together with some sheep.\nQuestion 2.\nAnd now for the weather forecast for this Saturday and Sunday. People heading to the music festival starting on Saturday on the South coast should be prepared for different conditions over the next two days. Saturday will bring bright sunshine but cool temperatures for this time of year. Overnight, however, clouds are expected to move in and Sunday will see dull skies bringing a further drop in temperatures, and there will be a good chance of rain later on.\nQuestion 3.\nHello. My name’s John Masters. This is a message for the person I spoke to yesterday in Customer Services. You asked me to return the iron I bought from you in its box. I’ve done this, although as I mentioned to you the box was badly damaged when it arrived. Anyway, that’s not the problem and the iron didn’t look damaged at all. But when I switched it on, it didn’t heat up. My order reference is 01376XB. I hope you’ll replace the iron as soon as possible. Thank you.\nQuestion 4.\nIn the heart of the City the Arts Centre includes a concert hall, cinema and an art gallery. The cinema is presenting a programme of films by younger film-makers and is attracting larger audiences than ever. The open-air concert area is the new home to the City Orchestra with an exciting concert programme of new composers and guest performers, while the City Art Gallery has a major programme of exhibitions all summer. Guests can enjoy dinner in the popular restaurant and enjoy the wonderful views of the City and river.\nQuestion 5.\nOn today’s student Cookery programme, I’m going to show you how to make some really cheap and healthy meals. Forget about opening tins and think fresh! You can do wonderful things with tomatoes, potatoes - and I don’t mean chips or fries! even cabbage, yes cabbage rolls, tilled with tasty rice and herbs. And the essential vegetable in all my recipes is the ordinary onion, red or white or brown colour doesn’t matter. First of all, you need a Sharp knife. So, watch carefully and off we go.\nQuestion 6.\nYou’d think that paying a bill would be easy. On tonight’s Money Today, I’m looking at some of the difficulties there can be. The story starts with my own experience. Thinking it’d be simpler, I made the mistake of trying to pay a hotel bill in cash. Well, amazingly they insisted on me using a credit card. I didn’t have one with me, so had to get onto my internet banking site using my mobile phone to try and get my card details. Nothing’s easy.\nQuestion 7.\nHello, this is Sarah Wright. I arranged to collect a guitar I ordered. I was meant to come this afternoon, but there’s a problem. I had to get a book from the library and I’ve just missed the bus so I won’t be able to get out to the shop before you close. I’ve got an appointment in the town centre to choose some new glasses tomorrow so I could come in and pick it up then. I hope that’s ok.\nQuestion 8.\nAnd now for the weather. What’s it going to be like for the big race tomorrow morning, Mike? Well, it’s been clear and sunny all week, but it looks as if it’s going to turn really cold tonight, and with ice on the track, conditions for racing could be difficult. It doesn’t look like there’ll be any rain until the weekend though, and later in the afternoon there’ll be a bit of sun coming out from behind the clouds.", questions: [{ q: "Where can visitors see the ducks?", options: ["in the cages", "in the pond", "near the wastebaskets", "in the field"], answer: 2 }, { q: "What will the weather be like when the festival starts?", options: ["sunny", "cloudy", "rainy", "rainy and cloudy"], answer: 0 }, { q: "What has the man sent back to the company?", options: ["an iron in a damaged box", "a damaged iron in a good condition box", "a damaged iron in a damaged box", "an iron in a good condition box"], answer: 0 }, { q: "Which part of the Arts Centre only opened recently?", options: ["an open-air concert area", "a cinema", "an art gallery", "a restaurant"], answer: 0 }, { q: "Which vegetable is used in all today's recipes?", options: ["tomatoes", "potatoes", "cabbage", "onion"], answer: 3 }, { q: "How did the man want to pay?", options: ["in cash", "by credit card", "by cheque", "bank transfer"], answer: 0 }, { q: "What is the woman phoning about?", options: ["a guitar", "a book", "glasses", "the library"], answer: 0 }, { q: "What will the weather be like for the race?", options: ["sunny", "snowy", "rainy", "cloudy"], answer: 1 }] } ], },
    { n: 2, title: "Part 2", hint: HINTS[2], recordings: [
      { id: "listening-20-p2", label: "Bài nghe Part 2", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-20/part1-2.mp3", script: "Conversation 1 (Q.9-12)\nW: Today I’m with Robin Marshall, who has just written a book about travelling in Argentina. Robin, tell us about yourself.\nM: Well, I’ve travelled to South America a lot for my work and I know Argentina well now. So well that I could be a tour guide if I wanted! I speak fluent Spanish, so I don’t need anyone to translate for me. My job involves travelling around selling products for my company. I meet a lot of people doing that, and I wanted to share those experiences with others, so I decided to try writing.\nW: So, tell us about your last visit to Argentina. What was the weather like?\nM: Well, it was winter there, so mornings were cold, but I’d expected that. Every day they said on the radio that it would be sunny later and sure enough, it was! I wanted to go sightseeing, and the weather was perfect for that.\nW: And where did you go when you went sightseeing?\nM: Well, I went to a wonderful market that sold everything from modern art to old recordings of traditional music, which I collect. I came home with a beautiful painting of the area I also saw a wonderful antique chair, but unfortunately it was too big to bring back.\nW: Now, Argentina is famous for its dancing. Did you see any performances during your trip?\nM: I did, yes. It reminded me of when I used to attend dance classes. I enjoyed them although I was never very good. I’m sure my teacher was pleased when I said I wasn’t going to continue! But these dancers made it look so easy that at that moment I felt like joining in and dancing with them.\nW: It sounds wonderful! And what else did you do?\nM: Well, I went to a small village on the coast. I took the bus there, and got a room in a small hotel. The hotel owner was very friendly. He took me down the river in his boat. It was very beautiful - you could see the forest in the distance.\nW: Do you have a favourite place in Argentina?\nM: Definitely. It’s a mountain near Buenos Aires. It’s famous for its spectacular scenery. But when I went there it was very misty and the sun was just rising. You couldn’t see much. There were no birds or animals about. It was totally quiet, and I loved that. I shall go back one day.\nW: We look forward to reading your book. Thank you, Robin.\nM: Thank you.\nConversation 2 (Q.13-16)\nW: Harry Park, you run a travel company which organizes adventure holidays in some difficult places? How did you first become interested in Adventure travel?\nM: Well, my father worked in an insurance company once he had a family but before that he’d spent several years traveling the world and he never stopped telling us about it. His stories were much more exciting than the books I read and they make me want to travel and have adventures of my own.\nW: And what made you decide to start an adventure travel company?\nM: Well, when I was in my twenties, I traveled a lot in different countries I went exploring and climbing in mountains and deserts. I wanted to show other people how wonderful these things were. The business has been very successful but when I started it I didn’t know if I’d make any money.\nW: Your company is called Far and wide. How did you choose the name?\nM: Well, I just called it Park Travel at first. But everyone thought that was terribly boring! My wife kept suggesting different things but in the end it was a customer who gave me the idea. Far and wide is also the title of a book that a friend wrote so it reminds me of him too.\nW: Great... The places you visit are usually very unspoilt, Harry. Some people think it’s not a good idea to take tourists there. What would you say to them?\nM: Well, most of the places we visit have no inhabitants, so we aren’t going to spoil people’s way of life or bring in things like television and fridges! And I make sure that we always take care of the environment. We are careful not to cause pollution, so we take all our rubbish away.\nW: Some of the things you do are also dangerous. Do you enjoy danger?\nM: Well, it’s not a question of enjoying it. It’s just that you can’t do what I do without thinking about the possible dangers. I’m never frightened though. If I’m taking a group up a mountain or something like that. I just concentrate on what I have to do and get on with it.\nW: You’ve been to some fascinating places, Harry. What’s your favourite?\nM: It’s in India. You travel along a river through spectacular scenery and up into the mountains in Madhya Pradesh. In the valley on the other side there’s a wonderful old castle. It’s magical. The mountains hide it, so few people know it’s there.\nW: Thanks for talking to us, Harry.\nM: Thank you.\nConversation 3 (Q.17-20)\nM: Now Linda, let’s talk about your first job.\nW: Well, I was an assistant in an expensive cake shop in the small town where I lived. It was my last year at school, before I went to college. I wanted to earn extra money for myself because I come from a family of seven and my parents couldn’t afford to give us much pocket money.\nM: Did you like your first boss?\nW: He was always polite, never shouted at us, even when we dropped thing and that was good for a young girl like me who wasn’t very confident. He knew everything about the business. I had no proper training, but it was good experience working for someone with so much knowledge. He didn’t pay us well, but I didn’t expect to earn much in my first job.\nM: And what about the shop? Was it a nice place to work?\nW: As I say, it was an expensive shop, and the cakes were beautiful. Then in the morning there was this wonderful smell of bread baking. The first week was difficult because I just wanted to eat the cakes which wasn’t allowed but then I lost interest in them. We had to keep everything clean, and that was hard work.\nM: Did you do any of the baking yourself?\nW: There were two chefs who were specialists in making cakes for celebrations and creating new bread recipes I loved watching them at work, but I wasn’t allowed to touch the ones on display in the windows. We sold sandwiches at lunchtime again, very luxurious ones and the shop assistants had to make those I learn to put in really generous fillings, much more than I used at home.\nM: How did you get on with the other shop assistants?\nW: One of them was my best friend, which was great, but the full-time staff some treated us like silly schoolgirls because we couldn’t cook. But I was surprised because the full-time assistants couldn’t add up in their head. I was good at it, but they used calculators if there was anything difficult to work out.\nM: Did you enjoy serving customers in the shop?\nW: The best part of the day was lunchtime, when we were busy. Time just flew. Then it was interesting when people came in to plan a party or a wedding. One of the chefs would come through to discuss the design of the cake. Some customers thought the prices were too high, but usually ended up buying the cakes anyway.", questions: [{ q: "What does Robin mainly do for a living?", options: ["He travels around Argentina to work as a professional tour guide", "He travels with tourists and helps them communicate in Spanish", "He travels abroad to write about the places he visits", "He travels to different places to sell products for his company"], answer: 3 }, { q: "What did Robin bring back from the market?", options: ["A painting showing the area he had visited", "An old recording of traditional Argentine music", "A piece of modern art that caught his attention", "An antique chair that he had wanted to buy"], answer: 0 }, { q: "How did Robin feel while watching the dancers?", options: ["He regretted having stopped attending dance classes", "He wanted to try dancing with them himself", "He realised that he had never been good at dancing", "He was surprised that the dancers found it so difficult"], answer: 1 }, { q: "What did Robin particularly enjoy about his favourite place?", options: ["The spectacular scenery around the mountain", "The peaceful atmosphere with almost nothing to see", "The chance to see a variety of birds and animals", "The clear view of the mountain in the morning sun"], answer: 1 }, { q: "Why did Harry decide to start an adventure travel company?", options: ["He wanted other people to experience places he found exciting", "He wanted to turn his father's travel stories into a business", "He wanted to make money from the countries he had visited", "He wanted to find a job that allowed him to travel more"], answer: 0 }, { q: "How was the name Far and Wide chosen?", options: ["Harry's wife suggested it after rejecting several other names", "A friend suggested it because it was the title of his book", "A customer suggested it after seeing the original company name", "Harry chose it because it described the company's travel plans"], answer: 2 }, { q: "How does Harry deal with the dangers involved in his work?", options: ["He thinks about possible dangers and concentrates on what he must do", "He avoids dangerous activities whenever they could put tourists at risk", "He accepts the danger because he finds challenging trips exciting", "He relies on his experience to prevent difficult situations from happening"], answer: 0 }, { q: "What particularly interests Harry about his favourite place in India?", options: ["A river that leads visitors through the mountains", "A remote valley surrounded by spectacular mountain scenery", "A spectacular mountain route that few tourists have discovered", "A hidden castle that can only be seen from the valley"], answer: 3 }, { q: "Why did Linda appreciate the way her first boss treated her?", options: ["He gave her useful training despite her having no previous experience", "He was patient with her mistakes and helped her feel more confident", "He paid her fairly even though she was still at school", "He trusted her to work independently despite her young age"], answer: 1 }, { q: "What did Linda find difficult about working in the cake shop?", options: ["Having to keep the shop clean and resisting the temptation to eat the cakes", "Having to prepare the bread while learning how to bake the cakes", "Having to work with the chefs while learning new recipes", "Having to serve customers while keeping the cakes in good condition"], answer: 0 }, { q: "What food did Linda help prepare for customers?", options: ["Special cakes for celebrations", "New types of bread", "Sandwiches for lunchtime", "Decorated cakes for the shop window"], answer: 2 }, { q: "What surprised Linda about the full-time shop assistants?", options: ["They were unable to do some calculations without using calculators", "They were unable to prepare food without help from the chefs", "They were unable to treat the younger assistants as experienced workers", "They were unable to explain how the shop's products were made"], answer: 0 }] } ], },
    { n: 3, title: "Part 3", hint: HINTS[3], recordings: [
      { id: "listening-20-p3", label: "Bài nghe Part 3", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-20/part1-3.mp3", script: "Talks/Lectures 1 (Q.21-25)\nWelcome to all of you. Can everybody see and hear me? Good. I’m Sally, your guide for this tour of the Bicentennial Park. I hope that you’re all wearing your most comfortable shoes and that you can keep up the pace. So let’s get under way on our tour around this wonderful park. I’ll start today with some general background information. There used to be a lot of factories in this area until the 1960s. Creating the park required the demolition of lots of derelict buildings on the site so most of the exciting park space all around you was originally warehouses and storehouses.\nThe idea of building a public park here was first discussed when a property developer proposed a high rise housing development, but the local community wasn’t happy. If the land was to be cleaned up they wanted to use the site for recreation. Residents wanted open space for outdoor activities rather than housing or even an indoor sports complex. Now to the Bicentennial Park itself. It has two areas, a nature reserve and a formal park with man made features and gardens. The tall blue and white building in front of us is called The Tower and it is the centre point for the formal gardens. It stands twelve metres high so follow me up the stairs to where we can take advantage of the fantastic views. Well here we are at the top of The Tower, and we’re going to look at the view from each direction. Out to the east, the large buildings about a kilometre away are on the Olympic site. There’s an indoor arena for gymnastics, a stadium for track and field and a swimming pool for races and synchronised swimming and also diving. If you look carefully down there, you can see the train lines.\nThe Olympic site has its own station to encourage the use of public transport. There is also a car park, but it only holds a limited number of cars. The formal park has some specially created water features. If you look out here to the south you can see a circular ornamental pond. And around to the west, you can relax and sit on a bench to smell the flowers in the rose garden and finally up to the north, if you look in front of you now there’s a lake with a small island in the centre you can hire rowing boats at the boat shed which you can’t see from here but if you look through the trees, you can see the café, which has lovely views across the water. Okay, let’s climb down now\nTalks/Lectures 2 (Q.26-30)\nWelcome to Green Vale Agricultural Park. As you know, we have only been open a week so you are amongst our first visitors. We have lots of fascinating indoor and outdoor exhibits on our huge complex, spreading hundreds of hectares. Our remit is to give educational opportunities to the wider public as well as to offer research sites for a wide variety of agriculturists and other scientists. Let’s start by seeing what there is to do. As you can see here on our giant wall plan, we are now situated in the Reception block ... here.\nAs you walk out of the main door into the park there is a path you can follow. If you follow this route you will immediately come into the Rare Breeds section where we keep a wide variety of animals which I shall be telling you a little more about later. Next to this ... moving east... is the large grazing area for the rare breeds. Then further east... in the largest section of our Park is the Forest Area. South of the grazing area and in fact just next to the Reception block is our Experimental Crop Area. In the middle of the Park ... this circular area is our lake These two small rectangular shapes here are the Fish Farms area we rear fish for sale. To the east of those is the marsh area which attracts a great many migrant birds.\nIn the south eastern corner, beyond the marsh, is our Market Garden area, growing vegetables and flowers. All these areas can be visited by the general public for almost all the year... although please take note of the large signs at the entrance to each area which tell which tell you when certain areas are being used for particular controlled experiments and are therefore temporarily out of bounds to the public. You can see for yourself what a huge area the park covers and a key question is always, how can we move around? Well you have a choice of means all environmentally friendly Cars are banned in the park. We have bicycles which you can hire behind the reception block here the healthy ones of you can go on foot and finally there’s our electric tram, powered from solar cells. You can find more information about this at the front entrance.\nA good place to start on your tour is the Rare Breeds section. We keep goats, sheep and hens and other kinds of poultry. We are also thinking of bringing in cows and horses but we do not, as yet, have facilities for these bigger animals. The animals are fed in public twice a day and a short lecture given on their feeding habits and nutritional needs. These are very popular with the public but of course we mustn’t lose sight of the main purpose of having this section not as such to preserve rare animals but to maintain the diversity of breeds to broaden the gene pool for agricultural development.\nTalks/Lectures 3 (Q.31-35)\nHello. I’m delighted to welcome you to our Wildlife Club and very pleased that you’re interested in the countryside and the plants and creatures of this area. I think you’ll be surprised at the variety we have here, even though we’re not far from London. I’ll start by telling you about some of the parks and open spaces nearby. One very pleasant place is Halland Common. This has been public land for hundreds of years and what you’ll find interesting is that the River Ouse which flows into the sea eighty kilometres away has its source in the Common. There’s an information board about the plants and animals you can see here and by the way, the Common is accessible 24 hours a day. Then there’s Holt Island which is noted for its great range of trees.\nIn the past willows were grown here commercially for basket making and this ancient craft has recently been reintroduced. The Island is only open to the public from Friday to Sunday, because it’s quite small and if there were people around every day much of the wildlife would keep away. From there it’s just a short walk across the bridge to Longfield Country Park. Longfield has a modern replica of a farm from over two thousand years ago. Children’s activities are often arranged there like bread making and face painting. The park is only open during daylight hours so bear that in mind if you decide to go there. Longfield Park has a programme of activities throughout the year and to give you a sample this is what’s happening in the next few days\nOn Monday you can learn about herbs and how they’ve been used over the centuries. You’ll start with a tour of our herb garden, practise the technique of using them as colour dyes for cloth and listen to an illustrated talk about their use in cooking and medicine. Then on Wednesday you can join local experts to discover the variety of insects and birds that appear in the evening. We keep to a small number of people in the group so if you want to go you’ll need to phone the park ranger a few days ahead.\nThere’s a small charge which you should pay when you turn up. I’m sure you’re all keen to help with the practical task of looking after the park so on Saturday you can join a working party. You’ll have a choice of all sorts of activities from planting hedges to picking up litter so you’ll be able to change from one to another when you feel like it. The rangers will be hard at work all day, but do come and join in, even for just a short while. One thing, though, is to make sure you’re wearing something that you don’t mind getting dirty or torn.\nNguồn: https://vstepowl.com/listening/de-thi/?exam=listening-20", questions: [{ q: "What does Sally's opening advice suggest about the tour?", options: ["Visitors will be able to choose between walking and cycling at each stage", "Visitors will need to walk at a steady pace and climb some stairs", "Visitors will mainly travel between different areas by public transport", "Visitors will spend most of the tour indoors to avoid the weather"], answer: 1 }, { q: "What can be inferred about the site before the park was created?", options: ["It had mainly been used for public recreation and indoor sports", "It had mainly been left undeveloped despite being close to the city", "It had mainly been used for industrial purposes and contained derelict buildings", "It had mainly been used for housing and other residential purposes"], answer: 2 }, { q: "Why did local residents oppose the proposed housing development?", options: ["They wanted the site to provide open space for outdoor activities", "They believed the proposed buildings would be too expensive to maintain", "They were concerned that new housing would increase traffic in the area", "They wanted the site to be used for a new indoor sports complex"], answer: 0 }, { q: "What is significant about The Tower?", options: ["It provides access to the nature reserve from the formal gardens", "It provides a central viewpoint over the formal gardens", "It provides visitors with information about the park's history", "It provides the main entrance to the formal gardens"], answer: 1 }, { q: "What is the purpose of the limited car parking at the Olympic site?", options: ["To reduce the amount of traffic passing through the park", "To ensure that enough space remains for public transport facilities", "To prevent visitors from parking close to the sports facilities", "To encourage visitors to use the train instead of driving"], answer: 3 }, { q: "What are the two main purposes of Green Vale Agricultural Park?", options: ["To conduct scientific experiments and sell agricultural products", "To educate the public and provide facilities for agricultural research", "To entertain visitors and provide training for agricultural students", "To educate farmers and develop commercial agricultural businesses"], answer: 1 }, { q: "What does the wall plan indicate about the Forest Area?", options: ["It is the main area used for experimental agricultural work", "It covers the area between the lake and the marsh", "It occupies the largest section of the park", "It is located directly beside the Rare Breeds section"], answer: 2 }, { q: "What does the speaker imply about getting around Green Vale?", options: ["Visitors have several environmentally friendly options for travelling around the park", "Visitors are encouraged to use public transport because private vehicles are restricted", "Visitors can use the electric tram only when travelling between the main exhibits", "Visitors are expected to use bicycles because walking between areas is difficult"], answer: 0 }, { q: "What does the speaker suggest about cows and horses at Green Vale?", options: ["They will replace some of the smaller animals currently on display", "They have already been introduced but are kept away from visitors", "They are unlikely to be introduced because the park lacks enough space", "They may be introduced later if suitable facilities become available"], answer: 3 }, { q: "Why does Green Vale maintain its Rare Breeds section?", options: ["To maintain genetic diversity that can support agricultural development", "To give visitors the opportunity to learn about traditional farm animals", "To provide researchers with animals for testing new farming methods", "To protect rare animals that are at risk of disappearing completely"], answer: 0 }, { q: "What is unusual about Halland Common?", options: ["It contains a large collection of trees that were originally planted commercially", "It can only be visited during certain hours because of its wildlife", "A major river begins there despite the Common being some distance from the sea", "It has remained private land even though people have used it for centuries"], answer: 2 }, { q: "Why is Holt Island only open to the public from Friday to Sunday?", options: ["Limiting visitors prevents the bridge from becoming overcrowded", "Limiting visitors gives people more opportunities to see the traditional craft", "Limiting visitors allows the island's trees to be managed more effectively", "Limiting visitors helps protect the wildlife on the relatively small island"], answer: 3 }, { q: "Which activity is specifically included in Monday's programme at Longfield Park?", options: ["Identifying local plants during a guided walk", "Using herbs to produce natural dyes for fabric", "Making medicines from herbs collected in the park", "Preparing traditional dishes using herbs from the garden"], answer: 1 }, { q: "What is required if visitors want to take part in Wednesday's activity?", options: ["They need to join a group that has already been organised", "They need to register at the park entrance earlier that same day", "They need to pay the activity fee before making a reservation", "They need to contact the park ranger several days beforehand"], answer: 3 }, { q: "What does the speaker imply about taking part in Saturday's working party?", options: ["Participants should bring suitable equipment because the park cannot provide it", "Participants must select one task in advance and complete it before leaving", "Participants can choose different tasks and do not have to stay all day", "Participants are expected to work all day because the rangers need extra help"], answer: 2 }] } ], },
  ] },
  { id: "listening-21", title: "Đề 21", subtitle: "35 câu · 40 phút", durationMin: 40, parts: [
    { n: 1, title: "Part 1", hint: HINTS[1], recordings: [
      { id: "listening-21-p1", label: "Bài nghe Part 1", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-21/part1-1.mp3", script: "Question 1.\nHi there. It’s Paul. I’ve been to the gallery to get some ideas for my latest project and I got some good ones you know, for shapes and so on now I need to think about using colours, and patterns. I might go back another day and look at paintings. There are some on the first floor of indoor scenes with vases and bowls in them like the ones I looked at on display today. Oh, and there’s a new sculpture exhibition on, but I didn’t get a chance to see it.\nQuestion 2.\nThere’s a new service available at Jeff Dean’s Gym from today. Consultant Jenny Law will offer gym members complete dietary analysis and fitness assessment. If you book before 5th November you will get a 33% discount and pay only 20 instead of the usual 30 pounds. Make sure you’re fit enough for the next century Consult the experts at Jeff Dean’s Gym. Join today!\nQuestion 3.\nYou have reached the Gas Hotline. If you have a complaint concerning our service you may speak to our customer care line by dialling 3 after the tone. If you would like to arrange for regular servicing to any of your gas appliances you may speak to our service engineers by dialling 4 after the tone. Our emergency service can be contacted by dialling 5 after the tone.\nQuestion 4.\nJust one last word, ladies and gentlemen. You probably know how dangerous rabies can be. Just one bite from an affected animal can kill if medical help is not available immediately. We’ve been free from rabies in Britain for over 75 years but it is still quite common here. So don’t be tempted to take animals home with you. They may be infected, and you can be sent to prison for illegally importing animals. Okay, now I need to tell you about...\nQuestion 5.\nAnd now for the week’s weather. The week will start out very wet. Indeed, with thunder and lightning in some areas. This will last through to Wednesday. Thursday will be dry but dull, but the clouds will clear during the night, bringing us a bright end to the week - something to make up for all that bad weather.\nQuestion 6.\nYes, I would agree that computers have made a dramatic difference in the workplace. However, computers in the home have their disadvantages especially for children. In a school setting they’re fine, I think, but letting them spend too much time with computer games certainly doesn’t help children learn to communicate. As to whether children have to think while they’re playing on the computer. I’d say they do.\nQuestion 7.\nAnd finally, on a lighter note. When college lecturer, Chris Pearse, told Jamie his pet bloodhound to fetch his slippers, he expected the dog to go upstairs for the new pair he had got for Christmas. In fact, the dog disappeared for two hours. The legendary nose of the bloodhound had led it four miles across town to the Council tip where Jamie retrieved his master’s old slippers, which had been thrown away and brought them home. Mr Pearse said, \"I didn’t expect it, but I can’t complain when he’s only done exactly what I asked.\"\nQuestion 8.\nWe are sorry to announce that both the 9.15 from Crewe and the 10:30 to London Euston have been cancelled due to staff shortages. Passengers for Birmingham International and Oxford should cross the bridge to platform four where a relief train will shortly arrive. Passengers for Reading can also take this train but must change at Oxford. Passengers for London and Heathrow airport should go immediately to the booking hall on platform one where a coach has been arranged.", questions: [{ q: "Which part of the gallery did the man visit?", options: ["paintings", "vases and bowls", "a sculpture exhibition", "photographs"], answer: 1 }, { q: "How much will a dietary and fitness assessment cost you?", options: ["£20", "£30", "£33", "£5"], answer: 0 }, { q: "Who do you contact when dialing number 4?", options: ["customer care department", "service engineering department", "emergency service department", "HR department"], answer: 1 }, { q: "Who is the message intended for?", options: ["people in Britain", "people leaving Britain", "people returning to Britain", "people visiting Britain"], answer: 2 }, { q: "What will the weather be like on Friday?", options: ["cloudy and dull", "sunny", "very wet", "cloudy"], answer: 1 }, { q: "Why should children not use computers?", options: ["They don’t encourage children to think.", "They keep children from doing their schoolwork.", "They stop children developing social skills.", "They are harmful to children’s eyes"], answer: 2 }, { q: "What did the dog do?", options: ["annoyed its master", "disobeyed its master", "obeyed its master", "fetched a thing its master didn’t ask"], answer: 2 }, { q: "What should passengers for London do?", options: ["take the train on platform four", "take the coach from the booking hall", "take the train on platform one", "change the train at Oxford"], answer: 1 }] } ], },
    { n: 2, title: "Part 2", hint: HINTS[2], recordings: [
      { id: "listening-21-p2", label: "Bài nghe Part 2", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-21/part1-2.mp3", script: "Conversation 1 (Q.9-12)\nM: Today we have with us in the studio Lucy Rainbow, who earns her living as a painter. Good morning, Lucy. Can you tell us about your job?\nW: Well, I don’t paint pretty pictures you can hang on your walls at home. Mainly I work in the theatre painting the background scenery for plays I’ve also done a couple of CD covers. That was great, because I got to meet my favourite pop stars.\nM: So how did all this start?\nW: Well, I always intended to become a proper artist. But I couldn’t sell any of my paintings, and anyway I got bored working alone! I was offered a job in an advertising agency but the idea of working in a theatre attracted me more. I get the chance to paint something different every day. I get paid reasonably well, and I work with a team of wonderful people.\nM: So you enjoy your work, but doesn’t it have any disadvantages?\nW: Mostly, I love it. The only thing that causes me stress is that often I have too many things to do at the same time while at other times I have nothing to do. It’s difficult to organise my time, but I always make sure I stop for lunch.\nM: How many hours do you work on an average day?\nW: There’s no such thing as an average day! But generally, I start work at eight in the morning, and go through until seven. That makes it an eleven-hour day, which is much longer than the eight hours that most people work.\nM: Is your journey to work difficult?\nW: Not really. My dream job would be one where I could walk to work but that hasn’t happened yet. I could drive to the theatre, but that makes me tired and I get a lot of my best ideas when I’m on my way to work, on the bus or train.\nM: Do you have time for any hobbies?\nW: Not as much as I’d like. I used to play a lot of tennis until I hurt my ankle and I was a regular visitor to an art gallery near my home until it closed down. In the little spare time I have, I’m doing a course in computer graphics. I hope what I learn will help me in my job.\nM: Well, thank you, Lucy. It’s been interesting talking to you.\nConversation 2 (Q.13-16)\nW: My guest today is Tim Jones, who organizes an international summer course for young musicians. Tim tell us all about it.\nM: Well, I’m lucky to have such a great job. Basically, young musicians come from all over the world and learn to play together as an orchestra. By the end of the six-week course, they’re really good and hearing them play is what gives me most pleasure. Unfortunately, I don’t get to know them all that well, as organizing every single detail of the course keeps me busy.\nW: So, how do you find the young musicians?\nM: We advertise on the Internet. Anyone between the ages of sixteen and twenty can complete the application form and email it to us along with a short recording of their playing. We’re not looking for perfect performances or the stars of tomorrow just people good enough to play in an orchestra. The course is in English but only a basic level of spoken language is necessary.\nW: And the teachers?\nM: The teachers are well-known musicians. Because they want to help young people, they do this work for a very low salary which is very kind of them. But it’s my job to take care of them and make sure they’re happy with their accommodation and so on. They generally have a great time, but some of them can be a bit difficult and sometimes complain about things.\nW: So where is the course held?\nM: In different places each year, actually, but it’s usually a university during the summer holidays. They have large halls for practicing, plus plenty of bedrooms and dining-rooms. Most importantly, though, the place has to have good rail, road and air connections so somewhere in the middle of the countryside’s no good.\nW: Do the students bring their own instruments?\nM: Mostly, yes. So, another thing to consider is security. Storing instruments in a locked room when they’re not being used is essential. Can you imagine a hundred or more musical instruments lying around violins, trumpets, flutes, cellos - all worth a lot of money. It would be terrible if one got damaged, or even worse stolen!\nW: And at the end of the course, there’s a concert tour.\nM: That’s right. I book concert halls and work out the programmes months in advance. It’s important to get it right. Ticket prices aren’t high, because we’re not a professional orchestra but lots of people buy them. We don’t make a profit, but take enough money to pay for the students’ travel and living expenses. It’s a fantastic experience for them.\nConversation 3 (Q.17-20)\nM: Today, I’m talking to Marta Stanston, who runs her own ‘mobile’ restaurant. Marta, How did you get into the restaurant business?\nW: Well, I learnt to cook at college. I always wanted to open my own restaurant but had no money so I got a job as a chef. I had all sorts of ideas for new dishes, which the staff thought would sell but the guy who owned the place wasn’t interested. That’s when a friend told me about the ‘mobile restaurant’ idea. It sounded great.\nM: Tell us about it.\nW: Well, it works like this: you decide on a menu obviously you have to be able to cook then you advertise it so people can book a meal. The most amazing thing is all the advertising is done through social-networking websites. People set up tables in their sitting-room, or in a City car park, an empty factory - anywhere in fact. And because you know how many people you’re cooking for, food doesn’t get wasted.\nM: So why was it good for you?\nW: Well, various reasons. Like, I could buy all the ingredients without risk because you make customers pay in advance. The greatest advantage, though, is by having a maximum of ten customers. I didn’t need to hire a waiter. Then, of course, I could prepare everything at home just take a camping gas cooker with me, plus some plates, glasses, knives and forks.\nM: Do you never run into problems?\nW: The whole experience is fun. People watch you cook and the atmosphere’s relaxed. I did one meal on a beach which almost went wrong because I didn’t think about the wind blowing sand into people’s food. Fortunately, I’d brought a large umbrella to protect myself from the sun so I put it around their table instead!\nM: And you sometimes use your own flat?\nW: If the weather’s bad, people come to my home instead, but it gets very crowded. Even though I’ve actually got enough chairs and a big table, it’s not ideal. I was worried we might disturb the neighbours but they’ve been alright about it. I love the temporary feel of the mobile idea, so home’s not really what it’s about.\nM: So, what’s the future of mobile restaurants?\nW: Well, it’s rather uncertain. Lots of new ones are popping up because it’s become fashionable. I think health inspectors will want to check them out. That doesn’t worry me, because I’m a trained chef. But if someone got ill in a less serious one, we might all get a bad name. So I guess inspections are a good thing.", questions: [{ q: "What kind of work does Lucy mainly do as a painter?", options: ["She creates scenery for theatre productions", "She produces artwork for music releases", "She paints portraits of well-known performers", "She makes pictures intended for people's homes"], answer: 0 }, { q: "What attracted Lucy to working in a theatre?", options: ["The chance to earn a much higher income", "The opportunity to work on varied projects", "The chance to avoid working with other people", "The opportunity to develop a career in advertising"], answer: 1 }, { q: "What does Lucy find difficult about managing her workload?", options: ["Her working hours often prevent her from taking breaks", "She sometimes has too much work and sometimes too little", "She is frequently required to work beyond her normal hours", "Her tasks are often difficult to complete without assistance"], answer: 1 }, { q: "Why does Lucy prefer travelling to work by public transport?", options: ["It allows her to develop ideas while travelling", "It saves her money compared with driving", "It helps her avoid becoming tired at work", "It gives her more time to prepare for the day"], answer: 0 }, { q: "What does Tim find most rewarding about running the course?", options: ["Helping the students settle into their accommodation", "Getting to know young musicians from different countries", "Seeing the students become better musicians", "Arranging opportunities for the students to perform"], answer: 2 }, { q: "Why are the teachers willing to work for relatively little money?", options: ["They hope to receive other benefits from the course", "They have fewer teaching responsibilities than usual", "They are given free transport during the course", "They are keen to contribute to young people's development"], answer: 3 }, { q: "Why would a remote countryside location be unsuitable for the course?", options: ["The students need access to large performance halls", "The teachers prefer to stay close to major cities", "Participants need convenient ways to reach the venue", "The course depends on nearby accommodation providers"], answer: 2 }, { q: "How is the money from the concert tour mainly used?", options: ["It helps finance the teachers' future work", "It covers the costs of running the concert venues", "It provides funding for the next year's course", "It helps meet the students' expenses during the tour"], answer: 3 }, { q: "Why did Marta become dissatisfied with her previous job as a chef?", options: ["Her employer was unwilling to try her new ideas", "Her colleagues regularly criticized her cooking", "She was given too little freedom to change the menu", "She found the working conditions increasingly difficult"], answer: 0 }, { q: "What feature of the mobile restaurant system particularly impressed Marta?", options: ["Customers can arrange meals in unusual locations", "Advertising can be handled entirely online", "Food can be prepared without professional equipment", "Customers can decide how many people attend"], answer: 1 }, { q: "What caused the problem during Marta's meal on the beach?", options: ["The food became too hot in the sun", "Unexpected rain interrupted the meal", "Sand was blown into the customers' food", "The cooking equipment stopped working properly"], answer: 2 }, { q: "Why does Marta think health inspections could benefit mobile restaurants?", options: ["They could prevent the business from becoming too popular", "They could help customers distinguish responsible operators", "They could reduce the number of new businesses entering the market", "They could ensure that every restaurant uses trained chefs"], answer: 1 }] } ], },
    { n: 3, title: "Part 3", hint: HINTS[3], recordings: [
      { id: "listening-21-p3", label: "Bài nghe Part 3", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-06/part1-3.mp3", script: "Talk 1 / Lecture 1:\nWelcome everybody to this presentation about creating a corporate image for your company. I wonder if, when you came in today, you thought, 'Hey, this guy hasn't got a suit on. This could be an interesting day!' You see, I believe that the way you dress is very important. I decided to come here rather casually dressed not because I wanted to make a fashion statement but because I wanted to let you know that this is not going to be a formal presentation. On the other hand, I want you to work hard and get something out of the day. I'm not wearing shorts and a T-shirt, for instance. So how would you describe the way I'm dressed?\nSmart but casual.\nExactly. But I also believe there are particular occasions when you need to wear a suit such as meeting a client – especially if you expect the client to be wearing one. Which brings me to a recent trend which we've picked up from the Americans: 'Dress down Friday'. How many of you are dressing more informally on a Friday? Quite a lot of you. How many of you go as far as wearing jeans? Not so many. Probably many of that small group work in the IT sector? I thought so.\nSo you see it's not just the day of the week or what clients may expect of you, it's the business you're in. If, for example, you work in a bank you're probably going to be in a dark suit every day of the week. And then there are those of us who are expected to wear a uniform. What you are doing here is projecting a very specific image of your company or service. Usually it's to do with reliability, expertise and efficiency. Customers and the general public feel reassured about someone in a recognisable uniform. Dress down Friday is a long way off for this group of employees. Now let's have a look at other ways in which a company projects its image...\nTalk 2 / Lecture 2:\nDo you get enough sleep at night? Do you ever feel tired during school? You may not be the only one. According to the National Sleep Foundation, kids aren't getting enough sleep. And it's affecting how they do in school.\nExperts say that kids need about ten hours of sleep each night. Your body needs sleep so it can rest for the next day. Animals need sleep to stay healthy. Cats and dogs sleep for about fifteen hours each day!\nSleep is also important for your brain. Just like your body, your brain needs a little vacation every night. Without enough sleep, students can't learn as well. They cannot pay attention, follow directions, or solve problems as well. Also, tired kids act in ways that they usually don't. They can easily get angry with their friends or get in trouble in class.\nScientists at the National Sleep Foundation talked to 1,400 kids. They asked them about their sleeping habits. They found that about seventy percent of kids were not getting enough sleep. The scientists think that soda and television are part of the reason. Drinks like cola, coffee, and tea have caffeine in them. Caffeine makes people stay awake. Kids who had drinks with caffeine got less sleep than other kids. Television is also a problem. When kids watch too much TV, they have to stay up later to finish their homework. Scientists also found that many kids had a TV in their room. These kids often stayed up late to watch a show.\nSo what can you do to make sure that you get enough sleep? Try not to drink anything with caffeine, especially at night. Sleep experts suggest that you try to go to bed at the same time every night. Don't do anything exciting before you go to bed. For instance, don't watch a scary movie or exercise. Try to do something relaxing, like reading a book or listening to quiet music.\nTalk 3 / Lecture 3:\nIf you have ever seen the northern lights, you know that they are one of most beautiful sights. People often seeing a faint glow appear on the horizon in the night sky. Then they may see wonderful colors such as green, red, blue, or purple stretch the sky. The shape of the northern lights can be straight lines, or it may be curved like the letter S, or round, just like a wheel. The colored lights and shapes move across the night sky, like ocean waves. No matter what the color or shape is, the northern lights are truly an amazing sight.\nMany people know them by their common name \"the northern lights.\" But do you know the meaning of the real name? The scientific name for the northern lights from Latin. It is aurora borealis. In English, the Latin word aurora translates to \"dawn,\" which means \"early morning.\" The Latin word borealis means \"northern.\" So aurora borealis can be translated as \"northern dawn,\" which describes the look of the northern sky in the very early morning.\nIf you have never seen aurora borealis, you are not alone. This natural phenomenon is not common in most parts of the world. In fact, many people travel or go on tours to places where they can see the northern lights. Where are these places? The best place to see aurora borealis is near the North Pole – the northernmost point of Earth – especially in areas such as northern Greenland, Scandinavia, and Alaska.\nMany years ago, before modern science, people developed stories, myths, and legends to explain natural phenomena such as aurora borealis. Finnish people called them \"fox fires,\" and believed the lights were caused when foxes made fires to keep warm. The Inuit people of northern Canada and Greenland believed that the aurora was the dance of animal spirits such as deer, seals, and whales.\nThe way the northern lights work is similar to a neon sign. Gas travels along magnetic lines. The lights occur when electric particles – electrons – collide with gas atoms, causing the atoms to give off light. The result is the amazing sweeps and waves of color that you can see. It's a wonderful sight if you happen to be in the right place at the right time.\nNguồn: https://vstepowl.com/listening/de-thi/?exam=listening-21", questions: [{ q: "Why does the speaker deliberately avoid dressing too casually for the presentation?", options: ["He wants to appear approachable without suggesting that the session lacks seriousness.", "He wants to demonstrate that fashion is becoming less important in business.", "He wants to follow the informal style preferred by most American companies.", "He wants to show that employees should be free to dress however they like."], answer: 0 }, { q: "What can be inferred about when wearing a suit is particularly appropriate?", options: ["When employees need to demonstrate their seniority to colleagues.", "When the business normally requires formal clothing every day.", "When the situation and the client's expected level of formality call for it.", "When employees want to create a stronger personal impression on clients."], answer: 2 }, { q: "What does the speaker's comment about jeans suggest about workplace dress codes?", options: ["The acceptability of informal clothing can depend on the industry.", "Employees in most industries are gradually abandoning formal clothing.", "Wearing jeans is generally considered inappropriate when meeting clients.", "Companies in the IT sector are expected to provide casual uniforms."], answer: 0 }, { q: "Why does a recognisable uniform reassure customers, according to the speaker?", options: ["It allows customers to identify which employees are available to help them.", "It demonstrates that the company follows a consistent fashion policy.", "It suggests that the company has recently improved its professional standards.", "It suggests that the wearer represents a reliable and competent service."], answer: 3 }, { q: "What do bank employees and uniformed employees have in common?", options: ["Their work normally allows them to dress informally on certain days.", "Their appearance is closely connected with the image their company projects.", "They are generally expected to interact with clients in similar situations.", "Their employers usually provide them with the clothes they are required to wear."], answer: 1 }, { q: "What is the main purpose of mentioning how long cats and dogs sleep?", options: ["To provide a comparison that highlights the importance of sufficient sleep.", "To suggest that children should follow animals' sleeping patterns.", "To show that animals experience the same academic problems as children.", "To introduce evidence that animals require more sleep than humans."], answer: 0 }, { q: "What does the comparison between the brain and the body emphasize?", options: ["The brain becomes less active when the body is physically tired.", "Both need regular rest in order to function effectively the next day.", "The brain requires a different type of rest from the rest of the body.", "The body needs more sleep than the brain because it uses more energy."], answer: 1 }, { q: "What broader effect of insufficient sleep does the speaker highlight?", options: ["It can affect students' behaviour as well as their ability to learn.", "It can make students rely more heavily on television for entertainment.", "It can cause students to lose interest in spending time with friends.", "It can make students unable to complete even simple school assignments."], answer: 0 }, { q: "Which factor was NOT mentioned as being associated with children's lack of sleep?", options: ["Consuming drinks containing caffeine.", "Watching television late at night.", "Having a television in the bedroom.", "Using electronic games before going to sleep."], answer: 3 }, { q: "What common principle underlies the sleep experts' recommendations?", options: ["Keeping evenings stimulating enough to avoid becoming tired too early.", "Creating a predictable and relaxing routine before going to bed.", "Reducing the amount of homework completed during the evening.", "Replacing screen-based activities with physical exercise at night."], answer: 1 }, { q: "What can be inferred from the speaker's description of the northern lights' movement?", options: ["Their appearance can vary considerably rather than remaining fixed in one form.", "Their movement is usually limited to straight lines across the horizon.", "Their colours become brighter whenever they form circular patterns.", "Their shape depends mainly on whether they appear in the early morning."], answer: 0 }, { q: "Why is the expression 'northern dawn' an appropriate translation of 'aurora borealis'?", options: ["It refers to the lights' connection with the northernmost parts of Earth.", "It describes both the direction and the early-morning appearance of the phenomenon.", "It explains why the phenomenon is most visible shortly after sunrise.", "It refers to the belief that the lights were caused by spirits at dawn."], answer: 1 }, { q: "Why does the speaker list Greenland, Scandinavia, and Alaska after mentioning the North Pole?", options: ["To identify regions where the phenomenon is especially likely to be observed.", "To compare the different explanations people have developed for the phenomenon.", "To show that tourism has become the main reason people study the northern lights.", "To explain why the phenomenon can be seen equally well throughout the northern hemisphere."], answer: 0 }, { q: "What do the Finnish and Inuit explanations have in common?", options: ["Both interpret the lights as natural events involving animals.", "Both developed explanations before people had modern scientific knowledge.", "Both believed the lights were produced by sources of heat in the sky.", "Both connected the lights with activities taking place near the North Pole."], answer: 1 }, { q: "What overall approach does the speaker take when explaining the northern lights?", options: ["He mainly describes their appearance while questioning traditional explanations.", "He focuses on the scientific process while briefly mentioning their cultural importance.", "He compares different locations in order to explain why the phenomenon is difficult to observe.", "He combines their appearance, cultural interpretations, location, and scientific explanation."], answer: 3 }] } ], },
  ] },
];
